import { useInView } from "./helpers";

export default function CaseFilesSection() {
  const [ref, visible] = useInView(0.15);

  return (
    <section style={{
      background: "linear-gradient(160deg, #0a0a18 0%, #111827 100%)",
      padding: "100px 6vw 80px",
      textAlign: "center",
    }}>

      {/* "Case Files" big heading */}
      <h1 className="sm:text-[105px] text-[50px]" style={{
        fontFamily: "'Inter','Helvetica Neue',sans-serif",
        fontWeight: 700,
        background: "linear-gradient(180deg, rgba(255,255,255,0.95) 0%, rgba(180,180,200,0.55) 100%)",
        WebkitBackgroundClip: "text",
        WebkitTextFillColor: "transparent",
        backgroundClip: "text",
        lineHeight: 1.0, margin: "0 0 18px",
        fontSize: "140px",
      }}>
        Case Files
      </h1>
      <p style={{
        fontFamily: "'Inter',sans-serif",
        fontSize: "30px",
        color: "rgba(255,255,255,1)",
        marginBottom: 72,
      }}>
        A closer look at real employee fraud cases
      </p>

      {/* Case title */}
      <h2 style={{
        fontFamily: "'Inter',sans-serif",
        fontSize: "clamp(22px,2.5vw,36px)",
        fontWeight: 800, color: "white",
        marginBottom: 40,
      }}>
        The Fake Referral Ring
      </h2>

      {/* Two suspect cards */}
      <div ref={ref} style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
        gap: 20, maxWidth: 980,
        margin: "0 auto",
      }}>

        {/* Suspect 1 */}
        <div style={{
          background: "rgba(255,255,255,0.05)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: 16,
          padding: "32px 28px",
          textAlign: "left",
          opacity: visible ? 1 : 0,
          transform: visible ? "translateY(0)" : "translateY(30px)",
          transition: "opacity 0.6s, transform 0.6s",
        }}>
          <p style={{
            fontFamily: "'Inter',sans-serif",
            fontSize: 15, fontWeight: 700,
            color: "#CE1010", marginBottom: 28,
            letterSpacing: 0.2,
          }}>Suspect 1</p>

          <div style={{ display: "flex", gap: 24, alignItems: "flex-start" }}>
            {/* Info */}
            <div style={{ flex: 1 }}>
              {[
                { label: "Name", value: "Vishal Taleja" },
                { label: "Date of Birth", value: "18th April 1995" },
                { label: "Gender", value: "Male" },
              ].map(row => (
                <div key={row.label} style={{ marginBottom: 20 }}>
                  <p style={{
                    fontFamily: "'Inter',sans-serif",
                    fontSize: 13, color: "rgba(255,255,255,0.45)",
                    margin: "0 0 3px",
                  }}>{row.label}</p>
                  <p style={{
                    fontFamily: "'Inter',sans-serif",
                    fontSize: 18, fontWeight: 700, color: "white",
                    margin: 0,
                  }}>{row.value}</p>
                </div>
              ))}
            </div>

            {/* Suspect 1 Photo */}
            <div style={{
              width: 130, height: 155, flexShrink: 0,
              borderRadius: 8,
              overflow: "hidden",
              border: "1px solid rgba(255,255,255,0.15)",
            }}>
              <img
                src="/assets/suspect1.png"
                alt="Vishal Taleja"
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  objectPosition: "top",
                }}
              />
            </div>
          </div>
        </div>

        {/* Accomplices */}
        <div style={{
          background: "rgba(255,255,255,0.05)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: 16,
          padding: "32px 28px",
          textAlign: "left",
          opacity: visible ? 1 : 0,
          transform: visible ? "translateY(0)" : "translateY(30px)",
          transition: "opacity 0.6s 0.15s, transform 0.6s 0.15s",
        }}>
          <p style={{
            fontFamily: "'Inter',sans-serif",
            fontSize: 16, fontWeight: 700,
            color: "#CE1010", marginBottom: 28,
          }}>The Accomplice Vishal's friends</p>

          <div style={{ display: "flex", gap: 24, alignItems: "flex-start" }}>
            {/* Friends list */}
            <div style={{ flex: 1 }}>
              {["Rahul", "Chavan", "Trivam"].map((name, i) => (
                <div key={name} style={{ marginBottom: 22 }}>
                  <p style={{
                    fontFamily: "'Inter',sans-serif",
                    fontSize: 13, color: "rgba(255,255,255,0.45)",
                    margin: "0 0 3px",
                  }}>Friend {i + 1}</p>
                  <p style={{
                    fontFamily: "'Inter',sans-serif",
                    fontSize: 18, fontWeight: 700, color: "white",
                    margin: 0,
                  }}>{name}</p>
                </div>
              ))}
            </div>

            {/* Stacked friend photos */}
            <div style={{ position: "relative", width: 160, height: 200, flexShrink: 0 }}>
              {[
                { src: "/assets/rahul.png", top: 0,  left: 55, rotate: 4,  zIndex: 1 },
                { src: "/assets/chavan.png",   top: 10, left: 10, rotate: -4, zIndex: 2 },
                { src: "/assets/trivam.png",   top: 90, left: 35, rotate: 2,  zIndex: 3 },
              ].map((photo, i) => (
                <div key={i} style={{
                  position: "absolute",
                  top: photo.top,
                  left: photo.left,
                  width: 90,
                  height: 108,
                  borderRadius: 6,
                  overflow: "hidden",
                  border: "2px solid rgba(255,255,255,0.25)",
                  transform: `rotate(${photo.rotate}deg)`,
                  zIndex: photo.zIndex,
                  boxShadow: "0 4px 16px rgba(0,0,0,0.5)",
                }}>
                  <img
                    src={photo.src}
                    alt={`Friend ${i + 1}`}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      objectPosition: "top",
                    }}
                  />
                </div>
              ))}
            </div>
          </div>
        </div>

      </div>
    </section>
  );
}
